import {sceneHeader,variantDialog,sceneDetails,sceneFamily,comparison,fitLabel} from './variants-ui.js?v=0.21.0';
import {currentScene,needsReview,allScenes} from './variants.js?v=0.21.0';
import {FITS} from './definitions.js?v=0.21.0';
import {sourceDetails} from '../shared/ancestry-ui.js?v=0.21.0';
import {derivedFrom} from '../shared/ancestry.js?v=0.21.0';
let compareScroll=0,openDetails=[];
import {boot,e,field,select,editAttrs} from '../creative-kit/ui.js?v=0.21.0';
import {make,validate,apply,markdown} from './state.js?v=0.21.0';
const labels={title:'Moment',actor:'Who is here?',trigger:'What just happened?',knows:'What do they know?',unknown:'What remains unknown?',can:'What can they do now?',stakes:'What is at stake?'};
function ideaCard(i,w){return `<article class="card intervention" data-drag-id="i:${e(i.id)}"><div class="card-top"><span>Intervention</span><button class="drag-handle" data-drag-handle data-action="move-menu" data-id="${e(i.id)}" aria-label="Move ${e(i.title)}">⠿</button></div><h3>${e(i.title)}</h3><p>${e(i.action||'Describe a change at this moment.')}</p><span data-fit-scene="${e(w.scene.id)}" data-fit-idea="${e(i.id)}" class="tag ${needsReview(w,currentScene(w),i)?'amber':''}">${e(fitLabel(w,currentScene(w),i))}</span><div class="card-actions"><button class="text-button" data-action="edit-idea" data-id="${e(i.id)}">Develop</button><button class="text-button" data-action="move-menu" data-id="${e(i.id)}">Move ↗</button></div></article>`;}
function render(w){compareScroll=document.querySelector('.scene-comparison-scroll')?.scrollLeft||0;openDetails=[...document.querySelectorAll('#app details[open][id]')].map(el=>el.id);const at=w.moments.findIndex(m=>m.id===w.selectedId);return `${sceneHeader(w)}<div class="section-head"><div><h2>Walk through the moment.</h2><p>Keep what the actor knows separate from what you know now. Place an intervention where it could help.</p></div><div class="toolbar"><button data-action="walk" data-direction="-1" ${at===0?'disabled':''}>← Previous</button><span class="micro">${at+1} / ${w.moments.length}</span><button data-action="walk" data-direction="1" ${at===w.moments.length-1?'disabled':''}>Next →</button><button data-action="add-moment" ${w.moments.length>=8?'disabled':''}>+ Moment</button></div></div><div class="scene-track">${w.moments.map((m,index)=>`<section class="moment ${m.id===w.selectedId?'current':''}" data-drop-id="m:${e(m.id)}"><article class="moment-body" data-drag-id="m:${e(m.id)}"><div class="card-top"><button class="step-number" data-action="select" data-id="${e(m.id)}" aria-label="Walk to ${e(m.title)}">${index+1}</button><button class="drag-handle" data-drag-handle data-action="order-menu" data-id="${e(m.id)}" aria-label="Reorder ${e(m.title)}">⠿</button></div><h3>${e(m.title)}</h3><span class="actor">${e(m.actor||'Name an actor')}</span><p class="trigger">${e(m.trigger||'What happens?')}</p><div class="knowledge-pair"><div><span>KNOWS</span><p>${e(m.knows||'What is visible?')}</p></div><div><span>DOES NOT KNOW</span><p>${e(m.unknown||'What is uncertain?')}</p></div></div><div class="moment-detail"><span>CAN DO</span><p>${e(m.can||'Available actions')}</p><span>AT STAKE</span><p>${e(m.stakes||'Consequences')}</p></div><div class="card-actions"><button class="text-button" data-action="edit-moment" data-id="${e(m.id)}">Edit scene</button><button class="text-button" data-action="order-menu" data-id="${e(m.id)}">Reorder ↗</button></div></article><div class="intervention-stack"><span class="eyebrow">WHAT COULD HELP HERE?</span>${w.ideas.filter(i=>i.momentId===m.id).map(i=>ideaCard(i,w)).join('')||'<div class="empty">Drop an intervention here.</div>'}<button data-action="add-idea" data-moment="${e(m.id)}">+ Intervention</button></div></section>`).join('')}</div><section class="unplaced panel" data-drop-id="unplaced"><div class="section-head"><div><h2>Possibilities waiting for a moment</h2><p>Drag a handle into the scene, or use Move. Reordering a moment changes the sequence and prompts a fresh fit check.</p></div><button data-action="add-idea">+ Unplaced idea</button></div><div class="idea-bank">${w.ideas.filter(i=>i.momentId===null).map(i=>ideaCard(i,w)).join('')||'<p class="hint">All interventions are placed. Drop one here to detach it.</p>'}</div></section>${comparison(w)}`;}
function editMoment(id,k){const m=k.w().moments.find(x=>x.id===id);k.open(Object.entries(labels).map(([f,label])=>field(`moment-${f}`,label,m[f],editAttrs('moments',id,f))).join('')+`<div class="toolbar"><button class="primary" data-action="close">Done</button><button class="delete" data-action="remove-moment" data-id="${e(id)}" ${k.w().moments.length===1?'disabled':''}>Remove moment</button></div><p class="hint">Removing a moment keeps its interventions in the unplaced bank.</p>`,'Edit this moment');}
function editIdea(id,k){const i=k.w().ideas.find(x=>x.id===id);k.open(sourceDetails(i.ancestry)+field('idea-title','Intervention',i.title,editAttrs('ideas',id,'title'))+field('idea-action','What changes at this moment?',i.action,editAttrs('ideas',id,'action'))+field('idea-assumption','What must be true for it to help?',i.assumption,editAttrs('ideas',id,'assumption'))+field('idea-test','How would you try it in a replay or rehearsal?',i.test,editAttrs('ideas',id,'test'))+(i.ancestry.parents.length?field('idea-changed','What differs in this variation?',i.changed,editAttrs('ideas',id,'changed'))+field('idea-reason','Why try it?',i.reason,editAttrs('ideas',id,'reason')):'')+`<section class="fit-editor"><h3>Fit in ${e(k.w().scene.title)}</h3><p>These are hypotheses to rehearse, not generated verdicts. Review again when the person, sequence, information or action changes.</p>`+select('idea-fit','How does it fit here?',i.fit,FITS,editAttrs('ideas',id,'fit'))+field('idea-fit-reason','Why, given this person and what they know?',i.fitReason,editAttrs('ideas',id,'fitReason'))+field('idea-fit-needs','What adaptation or condition is still needed?',i.fitNeeds,editAttrs('ideas',id,'fitNeeds'))+(i.checkedAgainst?`<details><summary>Context at the last review</summary>${sourceDetails(derivedFrom([i.checkedAgainst]))}</details>`:'')+`</section><div class="toolbar"><button class="primary" data-action="review" data-id="${e(id)}">Record review for this scene</button><button data-action="idea-branch" data-id="${e(id)}">Branch intervention</button><button data-action="close">Done</button><button class="delete" data-action="remove-idea" data-id="${e(id)}">Remove</button></div>`,'Develop the intervention');}
const kit=boot({route:'scenes',code:'S09',title:'Scene-first invention',description:'Make the situation concrete. Invent something that helps a particular person at a particular moment.',make,validate,apply,markdown,render,
 afterRender:()=>{const el=document.querySelector('.scene-comparison-scroll');if(el)el.scrollLeft=compareScroll;openDetails.forEach(id=>document.getElementById(id)?.setAttribute('open',''));},
 drop:(id,to,k)=>{const [type,item]=id.split(':');if(type==='i')k.act({type:'move-idea',id:item,momentId:to==='unplaced'?null:to.slice(2)});else if(to.startsWith('m:'))k.act({type:'reorder',id:item,before:to.slice(2)});},
 handle:(a,d,k)=>{if(a==='vary')k.open(variantDialog(k.w(),d.kind),'Create a scene variation');else if(a==='scene-details')k.open(sceneDetails(k.w()),'Scene notes');else if(a==='scene-family')k.open(sceneFamily(k.w()),'Scene branches');else if(a==='scene-open'){k.close();k.act({type:'scene-switch',id:d.id},{checkpoint:false});}else if(a==='review-cell'){k.act({type:'scene-switch',id:d.scene},{checkpoint:false});editIdea(d.id,k);}else if(a==='idea-branch'){const id=k.uid();if(k.act({type:'scene-idea-branch',id:d.id,newId:id}))editIdea(id,k);}else if(a.startsWith('scene-')){if(a==='scene-park'||a==='scene-remove')k.close();if(!k.act({type:a,id:d.id,sceneId:d.sceneId}))k.render();}else if(a==='edit-moment')editMoment(d.id,k);else if(a==='edit-idea')editIdea(d.id,k);else if(a==='add-moment'){const id=k.uid();if(k.act({type:a,id}))editMoment(id,k);}else if(a==='add-idea'){const id=k.uid();if(k.act({type:a,id,momentId:d.moment}))editIdea(id,k);}else if(a==='walk'){const index=k.w().moments.findIndex(m=>m.id===k.w().selectedId)+Number(d.direction);if(k.w().moments[index])k.act({type:'select',id:k.w().moments[index].id},{checkpoint:false});}else if(a==='select')k.act({type:a,id:d.id},{checkpoint:false});else if(a==='move-menu')k.open('<div class="dialog-options">'+k.w().moments.map(m=>`<button data-action="place" data-id="${e(d.id)}" data-moment="${e(m.id)}">${e(m.title)}</button>`).join('')+`<button data-action="place" data-id="${e(d.id)}">Keep unplaced</button></div>`,'Where could this help?');else if(a==='place'){k.close();k.act({type:'move-idea',id:d.id,momentId:d.moment||null});}else if(a==='order-menu')k.open('<p>Move this moment to another position in the sequence.</p><div class="dialog-options">'+k.w().moments.map((m,index)=>`<button data-action="reorder" data-id="${e(d.id)}" data-before="${e(m.id)}" ${m.id===d.id?'disabled':''}>Position ${index+1}: ${e(m.title)}</button>`).join('')+'</div>','Reorder scene');else if(['reorder','remove-moment','remove-idea','review'].includes(a)){k.close();k.act({type:a,id:d.id,before:d.before});}}
});

document.addEventListener('change',event=>{if(event.target.matches('[data-scene-switch]'))kit.act({type:'scene-switch',id:event.target.value},{checkpoint:false});});
document.addEventListener('submit',event=>{if(event.target.id!=='variant-form')return;event.preventDefault();const form=event.target,changes=Object.fromEntries([...form.querySelectorAll('[data-variation-field]')].map(el=>[el.dataset.variationField,el.value])),position=form.querySelector('#variation-position');if(kit.act({type:'scene-branch',id:kit.uid(),title:form.querySelector('#variation-title').value,reason:form.querySelector('#variation-reason').value,changed:({person:'Person and available action',information:'Known and unknown information',moment:'Trigger, stakes and position'})[form.dataset.kind],momentId:form.dataset.momentId,changes,...(position?{position:Number(position.value)}:{})})){kit.close();requestAnimationFrame(()=>document.getElementById('scene-picker')?.focus());}});

document.addEventListener('input',event=>{if(!event.target.hasAttribute('data-problem'))return;const w=kit.w(),scenes=allScenes(w);document.querySelectorAll('[data-fit-scene][data-fit-idea]').forEach(el=>{const s=scenes.find(s=>s.id===el.dataset.fitScene),i=s?.ideas.find(i=>i.id===el.dataset.fitIdea);if(i){el.textContent=fitLabel(w,s,i);el.classList.toggle(el.classList.contains('tag')?'amber':'stale',needsReview(w,s,i));}});});
